def _iter_sse_events(lines: Iterable[str]) -> Iterator[dict[str, str]]:
    """
    Minimal SSE parser that yields events as dicts with keys: event, data, id, retry.

    References: MCP Streamable HTTP transport allows text/event-stream responses.
    """

    event: dict[str, str] = {}
    data_lines: list[str] = []
    for raw in lines:
        line = (raw or "").rstrip("\n")
        if not line:
            if data_lines:
                event["data"] = "\n".join(data_lines)
            if event:
                yield dict(event)
            event = {}
            data_lines = []
            continue
        if line.startswith(":"):
            continue
        if ":" in line:
            field, value = line.split(":", 1)
            value = value.lstrip(" ")
        else:
            field, value = line, ""
        if field == "data":
            data_lines.append(value)
        elif field in {"event", "id", "retry"}:
            event[field] = value
    if data_lines:
        event["data"] = "\n".join(data_lines)
    if event:
        yield dict(event)


